import {today,daysBetween} from './model.js';
import {SCALE,quantityUnits} from './goal-math.js';
import {createGoal,addGoalProgress,editGoalProgress,changeGoalStatus,changeGoalDeadline,changeGoalIcon,saveGoalMilestone,deleteGoalMilestone,goalProgress,goalEarned,goalPercent,milestoneReached} from './goal-model.js';
const labels={active:'进行中',paused:'已暂停',abandoned:'已放弃',completed:'已完成'};
const number=value=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:6}).format(value);
const timestamp=value=>new Date(value).toLocaleString('zh-CN',{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const date=value=>value?value.replaceAll('-','.'): '未设置';
export function createGoalUI({getState,commit,modal:openModal,close,toast,esc,icon,iconPicker,head,render,navigate,confirm}){
 let tab='current',fieldSequence=0;
 function modal(title,body){openModal(title,body);document.querySelector('#dialog').scrollTop=0;}
 const getGoal=id=>{const goal=getState().goals.find(g=>g.id===id);if(!goal)throw new Error('目标不存在。');return goal};
 const goalStatus=goal=>`<span class="badge goal-status ${goal.status}">${labels[goal.status]}</span>`;
 function deadlineLabel(goal){const overdue=goal.status!=='completed'&&goal.deadline&&goal.deadline<today();return goal.deadline?`<span class="goal-deadline ${overdue?'overdue':''}">截止 ${date(goal.deadline)}${overdue?` · 已超期 ${daysBetween(today(),goal.deadline)} 天`:''}</span>`:'<span class="goal-deadline">未设截止日期</span>'}
 function progressBar(goal){return `<div class="progress goal-progress" role="progressbar" aria-label="${esc(goal.title)}完成进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${goalPercent(goal)}"><i style="width:${goalPercent(goal)}%"></i></div>`}
 function card(goal){return `<article class="card goal-card"><div class="row"><button class="goal-title" data-action="goal-detail" data-id="${goal.id}"><span class="goal-icon">${icon(goal.icon||'target')}</span><h3>${esc(goal.title)}</h3></button>${goalStatus(goal)}</div><div class="goal-amount"><strong>${number(goalProgress(goal))}</strong><span>/ ${number(goal.targetValue)} ${esc(goal.unit)}</span><b>${number(goalPercent(goal))}%</b></div>${progressBar(goal)}<div class="goal-card-meta">${deadlineLabel(goal)}<span>已获 ${number(goalEarned(goal))} 积分</span></div><div class="card-footer"><button class="text-btn" data-action="goal-detail" data-id="${goal.id}">详情与记录 ${icon('arrow')}</button>${goal.status==='active'?`<button class="btn" data-action="goal-progress" data-id="${goal.id}">+ Progress</button>`:goal.status==='paused'||goal.status==='abandoned'?`<button class="btn outline" data-action="goal-status" data-id="${goal.id}/active">恢复目标</button>`:'<span class="sub">已抵达终点</span>'}</div></article>`}
 function renderPage(){
  const goals=getState().goals,current=goals.filter(g=>g.status==='active'||g.status==='paused'),history=goals.filter(g=>g.status==='completed'||g.status==='abandoned'),list=tab==='history'?history:current;
  return `${head('Goals','一个明确的终点，一步步抵达。',`<button class="btn" data-action="goal-new">${icon('plus')} 新建目标</button>`)}<div class="section-tabs goal-tabs" role="group" aria-label="目标列表"><button data-action="goal-tab" data-id="current" class="${tab==='current'?'selected':''}" aria-pressed="${tab==='current'}">当前 · ${current.length}</button><button data-action="goal-tab" data-id="history" class="${tab==='history'?'selected':''}" aria-pressed="${tab==='history'}">历史 · ${history.length}</button></div>${list.length?`<div class="goal-grid">${[...list].reverse().map(card).join('')}</div>`:`<div class="card empty"><div class="empty-icon">${icon('goals')}</div><h3>${tab==='history'?'走过的路，会留在这里':'给目标一个明确的终点'}</h3><p>${tab==='history'?'已完成和已放弃的目标都会保留。<br>进度、奖励与每一次调整都有记录。':'100 道题、336 页书，或 100 km。<br>记录累计进度，抵达终点时收获奖励。'}</p>${tab==='current'?'<button class="btn" data-action="goal-new">创建第一个 Goal</button>':''}</div>`}`;
 }
 function milestoneRow(){const key=++fieldSequence;return `<div class="goal-milestone-input" data-goal-milestone-row><div><label for="goal-percent-${key}">百分比</label><div class="goal-input-suffix"><input id="goal-percent-${key}" name="percentage" type="number" inputmode="decimal" min="0.000001" max="99.999999" step="0.000001" placeholder="25" required><span>%</span></div></div><div><label for="goal-points-${key}">奖励积分</label><input id="goal-points-${key}" name="milestonePoints" type="number" inputmode="numeric" min="0" max="1000000" step="1" placeholder="50" required></div><button type="button" class="goal-remove-row" data-action="goal-remove-row" data-id="${key}" aria-label="移除此里程碑" data-goal-row-key="${key}">×</button></div>`}
 function createForm(){modal('新建 Goal',`<form id="goal-create-form" data-goal-form><p>用明确的总量定义目标。总量和完成奖励创建后固定保存。</p><label for="goal-title">标题</label><input id="goal-title" name="title" maxlength="60" required placeholder="例如：LeetCode 100 道">${iconPicker('target','目标图标')}<div class="field-row"><div><label for="goal-target">总进度</label><input id="goal-target" name="targetValue" type="number" inputmode="decimal" min="0.000001" max="1000000000" step="0.000001" required placeholder="100"></div><div><label for="goal-unit">单位</label><input id="goal-unit" name="unit" maxlength="12" required placeholder="题 / 页 / km"></div></div><label for="goal-deadline">截止日期 <span class="sub">可选</span></label><input id="goal-deadline" name="deadline" type="date"><label for="goal-completion-points">完成奖励 · Points</label><input id="goal-completion-points" name="completionPoints" type="number" inputmode="numeric" min="0" max="1000000" step="1" value="100" required><div class="goal-form-section"><h3>Milestones <span class="sub">可选</span></h3><p class="form-note">百分比须在 0% 与 100% 之间，100% 使用完成奖励。</p><div id="goal-milestone-fields"></div><button type="button" class="text-btn" data-action="goal-add-row">${icon('plus')} 添加里程碑</button></div><div class="modal-actions"><button class="btn" type="submit">创建 Goal</button></div></form>`)}
 function reveal(id){const goal=getGoal(id);tab=goal.status==='completed'||goal.status==='abandoned'?'history':'current';navigate();render();detail(id)}
 function milestoneView(goal){return `${[...goal.milestones].sort((a,b)=>a.percentage-b.percentage).map(m=>{const reached=milestoneReached(goal,m),locked=!!m.firstReachedAt;return `<div class="goal-milestone-row"><span class="goal-threshold ${reached?'reached':''}">${number(m.percentage)}%</span><div class="goal-milestone-copy"><strong>+${number(m.points)} Points</strong><small>${reached?'已达成 · 已发放':locked?'奖励已回滚 · 仍锁定':'尚未达成'}${locked?`<br>首次达成 ${timestamp(m.firstReachedAt)}`:''}</small></div>${locked?`<span class="goal-lock" aria-label="已锁定">${icon('lock')}</span>`:`<button class="text-btn" data-action="goal-edit-milestone" data-id="${goal.id}/${m.id}">编辑</button>`}</div>`}).join('')}<div class="goal-milestone-row"><span class="goal-threshold ${goal.status==='completed'?'reached':''}">100%</span><div class="goal-milestone-copy"><strong>+${number(goal.completionPoints)} Points</strong><small>${goal.status==='completed'?'完成奖励已发放':'Goal 完成奖励'}</small></div></div>`}
 function historyText(entry,goal){
  if(entry.type==='created')return '创建目标';
  if(entry.type==='deadline')return `截止日期：${date(entry.from)} → ${date(entry.to)}`;
  if(entry.type==='status')return `${labels[entry.from]} → ${labels[entry.to]}${entry.reason==='progress'?(entry.to==='completed'?' · 进度达到 100%':' · 修正进度后恢复'):''}`;
  const parts=entry.changes.map(change=>`${number(change.percentage)}% 里程碑${change.action==='grant'?'发放':'回滚'} ${number(change.points)} 分`);
  if(entry.completion)parts.push(`完成奖励${entry.completion==='grant'?'发放':'回滚'} ${number(goal.completionPoints)} 分`);
  return parts.join('；');
 }
 function detail(id){
  const goal=getGoal(id),progress=goalProgress(goal),events=goal.progressEvents;
  modal(goal.title,`<div class="goal-detail"><div class="row"><button class="goal-icon-edit" data-action="goal-icon" data-id="${id}" aria-label="更换目标图标"><span class="goal-icon">${icon(goal.icon||'target')}</span><span>更换图标</span></button>${goalStatus(goal)}</div><div class="goal-amount detail"><strong>${number(progress)}</strong><span>/ ${number(goal.targetValue)} ${esc(goal.unit)}</span><b>${number(goalPercent(goal))}%</b></div>${progressBar(goal)}<div class="goal-card-meta"><span>已获 ${number(goalEarned(goal))} 积分</span><span>${goal.status==='completed'?`完成于 ${timestamp(goal.completedAt)}`:'总进度创建后固定'}</span></div>${goal.status==='active'?`<button class="btn full goal-primary" data-action="goal-progress" data-id="${id}">+ Progress</button>`:goal.status==='completed'?'<p class="goal-state-note">已完成。仍可修正历史进度；不足 100% 时恢复为进行中。</p>':`<button class="btn outline full goal-primary" data-action="goal-status" data-id="${id}/active">恢复目标，继续推进</button>`}<section class="goal-detail-section"><div class="row"><h3>截止日期</h3><button class="text-btn" data-action="goal-deadline" data-id="${id}">修改</button></div>${deadlineLabel(goal)}<details class="goal-history"><summary>截止日期历史</summary><ul><li><span>原始截止日期：${date(goal.history[0].deadline)}</span><time>${timestamp(goal.createdAt)}</time></li>${goal.history.filter(e=>e.type==='deadline').map(e=>`<li><span>${date(e.from)} → ${date(e.to)}</span><time>${timestamp(e.at)}</time></li>`).join('')}</ul></details></section><section class="goal-detail-section"><div class="row"><h3>Milestones</h3><button class="text-btn" data-action="goal-edit-milestone" data-id="${id}">添加</button></div>${milestoneView(goal)}<p class="form-note">曾达成的里程碑保持锁定。奖励回滚后，重新达到时再发放。</p></section><section class="goal-detail-section"><h3>Progress History <span class="sub">· ${events.length}</span></h3>${events.length?`<div class="goal-event-list">${[...events].reverse().map((entry,i)=>`<div class="goal-event"><div class="row"><div><strong>+${number(entry.value)} ${esc(goal.unit)}</strong><time>${timestamp(entry.createdAt)}</time></div><button class="text-btn" data-action="goal-edit-progress" data-id="${id}/${entry.id}" aria-label="编辑进度记录 ${events.length-i}">编辑</button></div>${entry.edits.length?`<details class="goal-history"><summary>已修改 ${entry.edits.length} 次</summary><ul>${entry.edits.map(edit=>`<li><span>+${number(edit.from)} → +${number(edit.to)}</span><time>${timestamp(edit.at)}</time></li>`).join('')}</ul></details>`:''}</div>`).join('')}</div>`:'<p class="form-note">还没有进度记录，每一次推进都会留在这里。</p>'}</section><section class="goal-detail-section"><h3>生命周期与积分记录</h3><details class="goal-history"><summary>查看全部 ${goal.history.length} 条记录</summary><ul>${[...goal.history].reverse().map(entry=>`<li><span>${esc(historyText(entry,goal))}</span><time>${timestamp(entry.at)}</time></li>`).join('')}</ul></details></section>${goal.status==='active'||goal.status==='paused'?`<div class="modal-actions">${goal.status==='active'?`<button class="btn secondary" data-action="goal-status" data-id="${id}/paused">暂停目标</button>`:''}<button class="btn danger" data-action="goal-abandon" data-id="${id}">放弃目标</button></div><p class="form-note">暂停或放弃不会扣除已获积分，也不会更改截止日期。放弃后可从历史恢复。</p>`:''}</div>`);
 }
 function progressForm(key,editing=false){
  const [id,eventId]=key.split('/'),goal=getGoal(id),entry=editing?goal.progressEvents.find(e=>e.id===eventId):null;
  if(editing&&!entry)throw new Error('进度记录不存在。');
  if(!editing&&goal.status!=='active')throw new Error('请先恢复目标，再添加进度。');
  const max=(quantityUnits(goal.targetValue)-Math.round(goalProgress(goal)*SCALE)+(entry?quantityUnits(entry.value):0))/SCALE;
  modal(editing?'修改 Progress':'增加 Progress',`<form id="goal-progress-form" data-goal-form data-id="${id}" data-event-id="${entry?.id||''}"><p>${esc(goal.title)}<br>当前 ${number(goalProgress(goal))} / ${number(goal.targetValue)} ${esc(goal.unit)}</p>${entry?`<p>原记录：+${number(entry.value)} ${esc(goal.unit)} · ${timestamp(entry.createdAt)}</p>`:''}<label for="goal-progress-value">${editing?'这条记录的进度':'本次增加'}（${esc(goal.unit)}）</label><input id="goal-progress-value" name="value" type="number" inputmode="decimal" min="0.000001" max="${max}" step="0.000001" required ${entry?`value="${entry.value}"`:'autofocus placeholder="例如：3"'}><p class="form-note">${editing?'填写修改后的正数，无需输入负数。保存时会重新结算里程碑和完成奖励；若扣回积分后余额不足，此次修改不会保存。':`最多可增加 ${number(max)} ${esc(goal.unit)}，达到目标时自动完成并发放奖励。`}</p><div class="modal-actions"><button type="button" class="btn secondary" data-action="goal-detail" data-id="${id}">返回</button><button class="btn" type="submit">${editing?'保存并重新结算':'增加进度'}</button></div></form>`);
 }
 function iconForm(id){const goal=getGoal(id);modal('更换目标图标',`<form id="goal-icon-form" data-goal-form data-id="${id}"><p>${esc(goal.title)}</p>${iconPicker(goal.icon||'target','目标图标')}<div class="modal-actions"><button type="button" class="btn secondary" data-action="goal-detail" data-id="${id}">返回</button><button class="btn" type="submit">保存图标</button></div></form>`)}
 function deadlineForm(id){const goal=getGoal(id);modal('修改截止日期',`<form id="goal-deadline-form" data-goal-form data-id="${id}"><p>${esc(goal.title)}<br>当前截止日期：${date(goal.deadline)}</p><label for="goal-new-deadline">新的截止日期</label><input id="goal-new-deadline" name="deadline" type="date" value="${goal.deadline||''}"><p class="form-note">留空表示不设置截止日期。每次修改都会保留历史，目标状态不会改变。</p><div class="modal-actions"><button type="button" class="btn secondary" data-action="goal-detail" data-id="${id}">返回</button><button class="btn" type="submit">保存日期</button></div></form>`)}
 function milestoneForm(key){
  const [id,milestoneId]=key.split('/'),goal=getGoal(id),milestone=milestoneId?goal.milestones.find(m=>m.id===milestoneId):null;
  if(milestoneId&&!milestone)throw new Error('里程碑不存在。');if(milestone?.firstReachedAt)throw new Error('已达成过的里程碑不能修改。');
  modal(milestone?'编辑里程碑':'添加里程碑',`<form id="goal-milestone-form" data-goal-form data-id="${id}" data-milestone-id="${milestone?.id||''}"><p>${esc(goal.title)} · 当前 ${number(goalPercent(goal))}%</p><label for="goal-milestone-percentage">达到百分之几</label><input id="goal-milestone-percentage" name="percentage" type="number" inputmode="decimal" min="0.000001" max="99.999999" step="0.000001" required value="${milestone?.percentage||''}" placeholder="25"><label for="goal-milestone-points">奖励积分</label><input id="goal-milestone-points" name="points" type="number" inputmode="numeric" min="0" max="1000000" step="1" required value="${milestone?.points??50}"><p class="form-note">设置到当前进度以内会立即发奖并锁定。100% 使用 Goal 完成奖励。</p><div class="modal-actions"><button type="button" class="btn secondary" data-action="goal-detail" data-id="${id}">返回</button><button class="btn" type="submit">保存里程碑</button></div>${milestone?`<button type="button" class="text-btn goal-delete" data-action="goal-delete-milestone" data-id="${id}/${milestone.id}">删除未达成的里程碑</button>`:''}</form>`);
 }
 function resultMessage(result){return result.status==='completed'?`目标已完成${result.pointsDelta>0?`，+${result.pointsDelta} Points`:''}`:result.pointsDelta>0?`已保存，+${result.pointsDelta} Points`:result.pointsDelta<0?`已保存，扣回 ${-result.pointsDelta} Points`:'已保存'}
 const actions={
  'goal-tab':value=>{if(['current','history'].includes(value)){tab=value;render()}},
  'goal-icon':iconForm,'goal-new':createForm,'goal-detail':detail,'goal-progress':key=>progressForm(key),'goal-edit-progress':key=>progressForm(key,true),'goal-deadline':deadlineForm,'goal-edit-milestone':milestoneForm,
  'goal-add-row':()=>{const container=document.querySelector('#goal-milestone-fields');if(container.children.length>=50)throw new Error('最多设置 50 个里程碑。');container.insertAdjacentHTML('beforeend',milestoneRow())},
  'goal-remove-row':key=>document.querySelector(`[data-goal-row-key="${key}"]`)?.closest('[data-goal-milestone-row]').remove(),
  'goal-status':key=>{const [id,status]=key.split('/');commit(s=>changeGoalStatus(s,id,status));reveal(id);toast(status==='active'?'目标已恢复':'目标已暂停')},
  'goal-abandon':id=>confirm('放弃这个目标？','原进度、积分和全部历史会保留。之后可以从 Goals 历史中恢复。','goal-confirm-abandon',id,'放弃并保留记录'),
  'goal-confirm-abandon':id=>{commit(s=>changeGoalStatus(s,id,'abandoned'));reveal(id);toast('已移入目标历史，随时可以恢复')},
  'goal-delete-milestone':key=>confirm('删除这个未达成的里程碑？','该里程碑尚未发放积分，删除不会影响现有进度或余额。','goal-confirm-delete-milestone',key,'删除里程碑'),
  'goal-confirm-delete-milestone':key=>{const [id,milestoneId]=key.split('/');commit(s=>deleteGoalMilestone(s,id,milestoneId));detail(id);toast('未达成的里程碑已删除')}
 };
 function submit(form){
  const data=new FormData(form),id=form.dataset.id;
  if(form.id==='goal-create-form'){
   const milestones=[...form.querySelectorAll('[data-goal-milestone-row]')].map(row=>({percentage:Number(row.querySelector('[name="percentage"]').value),points:Number(row.querySelector('[name="milestonePoints"]').value)}));
   const goal=commit(s=>createGoal(s,{title:data.get('title').trim(),icon:data.get('icon'),targetValue:Number(data.get('targetValue')),unit:data.get('unit').trim(),completionPoints:Number(data.get('completionPoints')),deadline:data.get('deadline')||null,milestones}));reveal(goal.id);toast('新目标已创建');return;
  }
  if(form.id==='goal-icon-form'){commit(s=>changeGoalIcon(s,id,data.get('icon')));reveal(id);toast('目标图标已更新');return}
  let result;
  if(form.id==='goal-progress-form')result=commit(s=>form.dataset.eventId?editGoalProgress(s,id,form.dataset.eventId,Number(data.get('value'))):addGoalProgress(s,id,Number(data.get('value'))));
  if(form.id==='goal-deadline-form')result=commit(s=>changeGoalDeadline(s,id,data.get('deadline')||null));
  if(form.id==='goal-milestone-form')result=commit(s=>saveGoalMilestone(s,id,{percentage:Number(data.get('percentage')),points:Number(data.get('points'))},form.dataset.milestoneId||null));
  reveal(id);toast(resultMessage(result));
 }
 return {renderPage,actions,submit};
}
